{%- import 'authfly/components.html.twig' as af -%}
{%- set id = p.id ?? '' -%}{%- set l = p.labels ?? {} -%}{%- set error = p.error ?? '' -%}
{%- set formError = error ? id ~ '-error' : null -%}
{%- set c5 -%}
{{ af.head(id, p.title ?? '', p.text ?? '') }}
{{ af.messages(id, error, '') }}
{%- if (p.social ?? 'none') == 'show' -%}
{%- set c2 -%}{%- for pr in p.providers ?? [] -%}
{%- set c1 -%}{{ af.icon(pr.icon ?? '') }}{{ pr.title ?? '' }}{%- endset -%}
{{ af.button((l.socialUrl ?? '') ~ '/' ~ (pr.id ?? ''), '', af_skin('button', 'outline', 'w-full'), {'data-provider': pr.id ?? null}, c1) }}
{%- endfor -%}{%- endset -%}{{ af.stack('2', '', '', '', {'role': 'group', 'aria-label': l.providers ?? null, 'data-testid': 'authfly-providers'}, c2) }}
{%- endif -%}
{%- set c3 -%}{{ af.hidden('csrf', p.csrf ?? '') }}
{{ af.field({'label': l.identifier ?? '', 'for': id ~ '-identifier', 'formError': formError, 'input': {'type': (p.identifier ?? 'any') == 'email' ? 'email' : 'text', 'name': 'identifier', 'required': true, 'attrs': {'autocomplete': (p.identifier ?? 'any') == 'email' ? 'email' : 'username'}}}) }}
{%- if (p.method ?? 'password') == 'password' -%}
{{ af.field({'label': l.password ?? '', 'for': id ~ '-password', 'formError': formError, 'input': {'type': 'password', 'name': 'password', 'required': true, 'attrs': {'autocomplete': 'current-password'}}}) }}
{%- if l.forgot ?? '' -%}
{{ af.link(l.forgotHref ?? '', af_skin('link', 'w-fit text-sm'), 'forgot', l.forgot ?? '') }}
{%- endif -%}
{%- endif -%}
{{ af.button('', 'submit', af_skin('button', 'default', 'w-full'), {'data-testid': 'submit'}, af_esc(l.submit ?? '')) }}{%- endset -%}
{{ af.form(p.action ?? '', '', {'data-testid': 'authfly-form'}, c3) }}
{%- if l.magic ?? '' -%}
{{ af.button(l.magicHref ?? '', '', af_skin('button', 'outline', 'w-full'), {'data-testid': 'switch-method'}, af_esc(l.magic ?? '')) }}
{%- endif -%}
{%- if l.signupLink ?? '' -%}
{%- set c4 -%}{{ l.signupText ?? '' }} {{ af.link(l.signupHref ?? '', af_skin('link'), 'signup-link', l.signupLink ?? '') }}{%- endset -%}
{{ af.text('', af_text('muted'), {}, c4) }}
{%- endif -%}
{%- endset -%}
{{ af.card(af_skin('widgetCard'), {'data-testid': 'authfly-sign-in'}|merge({'aria-labelledby': (p.landmarkLabel ?? '') ? null : id ~ '-title', 'aria-label': p.landmarkLabel ?? null}), c5) }}
